using System;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class SecurityCenterPage:UserControl{public SecurityCenterPage(){if(!AppSession.Can("Users.Manage")){Controls.Add(Ui.Label(L.Fa?"دسترسی ندارید":"Access denied",16,true));return;}Dock=DockStyle.Fill;AutoScroll=true;var p=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true};p.Controls.Add(Ui.Label(L.Fa?"مرکز امنیت":"Security Center",20,true));Add(p,L.Fa?"کاربران غیرفعال":"Inactive users",Database.Scalar("SELECT COUNT(*) FROM Users WHERE IsActive=0"));Add(p,L.Fa?"رویدادهای ثبت‌شده امروز":"Audit events today",Database.Scalar("SELECT COUNT(*) FROM AuditLog WHERE CAST(CreatedAt AS date)=CAST(GETDATE() AS date)"));Add(p,L.Fa?"نقش‌های دارای دسترسی سفارشی":"Roles with custom permissions",Database.Scalar("SELECT COUNT(DISTINCT RoleName) FROM RolePermissions"));Add(p,L.Fa?"قالب‌های ایمیل فعال":"Active email templates",Database.Scalar("SELECT COUNT(*) FROM EmailTemplates WHERE IsActive=1"));var note=Ui.Label(L.Fa?"پیشنهاد امنیتی: رمزهای قوی، حداقل دسترسی، پشتیبان‌گیری منظم و بررسی Audit Log را اجرا کنید.":"Security guidance: enforce strong passwords, least privilege, regular backups and audit-log reviews.",11);note.MaximumSize=new Size(850,0);p.Controls.Add(note);Controls.Add(p);}void Add(FlowLayoutPanel p,string name,object value){var c=Ui.Card();c.Width=520;c.Height=72;var l=Ui.Label(name+"   •   "+Convert.ToString(value),13,true);c.Controls.Add(l);p.Controls.Add(c);}}}
